{"content":"// Articulated one-piece-print snake, PLA / 0.4 mm nozzle / 0.2 mm layers
// Units: mm. Print flat with Z vertical. Neutral assembly lies along +X.
$fn = 64;

// Core layout
segment_count = 6;
pitch = 22;
body_width = 14;
body_height = 8;
body_start = 4.0;
body_end = 18.0;

// Captive Z-axis pin joint. Designed radial clearance = 0.50 mm.
shaft_r = 1.50;
pin_head_r = 3.00;
socket_inner_r = 3.50;
socket_outer_r = 4.80;
radial_clearance = socket_inner_r - pin_head_r; // 0.50
pin_shaft_z0 = 0.55;
pin_shaft_z1 = 1.55;
pin_head_z0 = 1.55;
pin_head_z1 = 2.10;
retainer_bottom_z = 2.60;
retainer_top_z = 3.20;
axial_clearance = retainer_bottom_z - pin_head_z1; // 0.50
socket_bottom_z = 0.55;
socket_wall_top_z = 2.70;
retainer_inner_r_top = 2.90;
retainer_inner_r_bottom = retainer_inner_r_top + (retainer_bottom_z - (retainer_bottom_z-0.60));
// The retainer underside tapers inward 0.6 mm over 0.6 mm height (45 degree self-supporting).
opening_half_angle = 20; // 40-degree opening, narrower than captured pin head

// Render selector: 0 = full neutral assembly; 1..6 = individual link, same global coordinates
part = 0;

module ellipsoid_at(x,y,z,rx,ry,rz) {
    translate([x,y,z]) scale([rx,ry,rz]) sphere(r=1);
}
module body_shell(i) {
    // Low, rounded, tapered segments with a slightly larger head and tapered tail.
    if (i == 0) {
        hull() {
            ellipsoid_at(body_start+1,0,body_height/2,2.7,body_width/2,body_height/2);
            ellipsoid_at(body_end-2,0,body_height/2,4.0,body_width/2,body_height/2);
            translate([body_end+1,0,body_height/2]) scale([1,0.58,0.65]) sphere(r=4.1);
        }
        // Two raised eyes, fused into the head; no separate printed parts.
        for (s=[-1,1]) translate([body_end-1.0,s*4.1,body_height-0.20])
            scale([1,0.72,0.42]) sphere(r=1.25);
    } else {
        hull() {
            ellipsoid_at(body_start+1,0,body_height/2,2.5,body_width/2,body_height/2);
            ellipsoid_at(body_end-1,0,body_height/2,3.5,body_width/2,body_height/2);
        }
    }
}
module male_pin() {
    // Pin, mushroom head and root arm are one continuous solid. Chamfered head underside.
    hull() {
        translate([pitch-4.8,0,body_height/2]) scale([2.5,2.2,1.6]) sphere(r=1);
        translate([pitch-1.5,0,0.8]) cylinder(r=1.8,h=0.5);
    }
    translate([pitch,0,pin_shaft_z0]) cylinder(r=shaft_r,h=pin_shaft_z1-pin_shaft_z0);
    translate([pitch,0,pin_head_z0]) cylinder(r=pin_head_r,h=pin_head_z1-pin_head_z0);
    // Bevel under the pin head reduces sharp overhangs; shaft remains the rotary journal.
    translate([pitch,0,pin_shaft_z1-0.01]) cylinder(r1=shaft_r,r2=pin_head_r,h=0.30);
}
module female_socket() {
    // C-shaped lower bearing ring and upper retaining lip. Slot faces -X; arm joins body +X.
    difference() {
        union() {
            // Lower C-ring
            translate([0,0,socket_bottom_z]) linear_extrude(height=socket_wall_top_z-socket_bottom_z)
                difference() { circle(r=socket_outer_r); circle(r=socket_inner_r); }
            // Upper retaining arc, with a 45-degree tapered underside built from a rotated extrusion.
            // The lip is an annular sector; its lower inner edge is 0.6 mm wider than its top edge.
            translate([0,0,retainer_bottom_z]) linear_extrude(height=retainer_top_z-retainer_bottom_z)
                difference() { circle(r=socket_outer_r); circle(r=retainer_inner_r_top); }
            // Retainer root arm tied to the forward (+X) side of the ring and the link body.
            hull() {
                translate([2.8,0,2.1]) cylinder(r=1.7,h=0.9,center=true);
                translate([5.0,0,body_height/2]) scale([2.0,2.5,1.6]) sphere(r=1);
            }
        }
        // Radial opening centered at -X; it stays clear of the pin throughout nominal +/-25 degrees.
        rotate([0,0,180]) rotate_extrude(angle=2*opening_half_angle)
            translate([0,-0.1,0]) square([socket_outer_r+1,retainer_top_z+1]);
        // Remove opening from ring at every relevant height; radial wedge starts at axis.
        for (z=[socket_bottom_z,retainer_bottom_z])
            translate([0,0,z]) linear_extrude(height=(z==socket_bottom_z ? socket_wall_top_z-socket_bottom_z : retainer_top_z-retainer_bottom_z))
                polygon(points=[[0,0],[-(socket_outer_r+1)*sin(opening_half_angle),-(socket_outer_r+1)*cos(opening_half_angle)],[-(socket_outer_r+1)*sin(opening_half_angle),(socket_outer_r+1)*cos(opening_half_angle)]]);
    }
}
module link(i) {
    union() {
        body_shell(i);
        // female eye is present on the five body segments only
        if (i > 0) female_socket();
        // male pin is present on the head and first four body segments only
        if (i < segment_count-1) male_pin();
    }
}
module assembly() {
    for (i=[0:segment_count-1]) translate([i*pitch,0,0]) link(i);
}

if (part == 0) assembly();
else if (part >= 1 && part <= segment_count) translate([(part-1)*pitch,0,0]) link(part-1);

// Documented neutral envelope: approximately 136 x 28 x 8 mm including head and joint features.
// Five independent yaw joints: nominal usable range at least -25..+25 degrees around Z.
","file_path":"/app/output/model.scad","justification":"","sandbox_permissions":"danger-full-access"}

